// 4-bit wrapping counter used as the end-to-end toolchain smoke test.
module counter (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       en,
    output logic [3:0] count
);
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 4'd0;
        end else if (en) begin
            count <= count + 4'd1;
        end
    end

`ifdef FORMAL
  // ---- generated by formalsynapse.sva_lower; do not edit ----
  logic [7:0] f_fsyn_cycles;
  initial f_fsyn_cycles = '0;
  always @(posedge clk) begin
    if (f_fsyn_cycles != 8'd255) f_fsyn_cycles <= f_fsyn_cycles + 1'b1;
  end
  // a_counter_inc: assert property (p_counter_inc)
  always @(posedge clk) begin
    if (f_fsyn_cycles >= 8'd2 && (rst_n) && $past(rst_n, 1)) begin
      if ($past(en, 1))
        a_counter_inc: assert((count == $past(count) + 4'd1));
    end
  end
  // a_counter_hold: assert property (p_counter_hold)
  always @(posedge clk) begin
    if (f_fsyn_cycles >= 8'd2 && (rst_n) && $past(rst_n, 1)) begin
      if ($past(!en, 1))
        a_counter_hold: assert((count == $past(count)));
    end
  end
  // c_counter_en: cover property (@(posedge clk) disable iff (!rst_n) en);
  always @(posedge clk) begin
    if (f_fsyn_cycles >= 8'd0 && (rst_n)) begin
      c_counter_en: cover((en));
    end
  end
  // c_counter_wrap: cover property (@(posedge clk) disable iff (!rst_n) en && count == 4'hF);
  always @(posedge clk) begin
    if (f_fsyn_cycles >= 8'd0 && (rst_n)) begin
      c_counter_wrap: cover((en && count == 4'hF));
    end
  end
`endif
endmodule
